class Solution {
public:
    int countPoints(string rings) {
        int rods[10] = {0};
        int n = rings.size();
        for (int i = 0; i + 1 < n; i += 2) {
            char color = rings[i];
            int rod = rings[i + 1] - '0';
            int bit = (color == 'R') ? 1 : (color == 'G') ? 2 : 4;
            rods[rod] |= bit;
        }
        int ans = 0;
        for (int i = 0; i < 10; i++) {
            if (rods[i] == 7) ans++;
        }
        return ans;
    }
};
